    notes.push("\u0636\u063A\u0637 \u0627\u0644\u0648\u0642\u062A \u0648\u0627\u0644\u0625\u062C\u0647\u0627\u062F \u0645\u062D\u0631\u0643 \u0644\u0644\u0628\u062D\u062B \u0639\u0646 \u062D\u0644\u0648\u0644 \u062C\u0627\u0647\u0632\u0629");
