  const feedbackRequired = feedbackTriState === "required" || deliveryList.includes("critique_feedback");
  const feedbackConfirmedNotRequired = feedbackTriState === "not_required" && !deliveryList.includes("critique_feedback");
  const accountabilityRequired = accountabilityTriState === "required" || deliveryList.includes("accountability");
  const accountabilityConfirmedNotRequired = accountabilityTriState === "not_required" && !deliveryList.includes("accountability");
  const isZeroTouch = answers.creatorTimePerCustomer === "almost_none" || answers.creatorTimePerCustomer === "under_30m";
  const isRecurringSupport = answers.creatorTimePerCustomer === "recurring_support";
  const isHighTouch = answers.creatorTimePerCustomer === "high_touch" || answers.creatorTimePerCustomer === "1_to_2h";
